command:
// K — Rolar novamente — 1x por cena, para quem tiver o poder "Parceiro: K (Veterano)"
actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("Selecione o token do herói que K está ajudando.");
if (!actor.items.some((i) => i.name === "Parceiro: K (Veterano)")) return ui.notifications.warn(actor.name + " não tem o poder do K na ficha.");
const MARCA = "K — rolagem novamente usada";
if (actor.effects.some((e) => e.name === MARCA)) return ui.notifications.warn("K já ajudou " + actor.name + " a rolar novamente nesta cena.");

// último teste deste ator no chat (ignora rolagens de dano)
const msg = game.messages.contents.slice().reverse().find((m) =>
	m.speaker?.actor === actor.id && m.rolls?.some((r) => r.dice?.some((d) => d.faces === 20)));
if (!msg) return ui.notifications.warn("Nenhum teste recente de " + actor.name + " encontrado no chat.");
const original = msg.rolls.find((r) => r.dice?.some((d) => d.faces === 20));
const titulo = (msg.flavor || msg.content.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim().slice(0, 60)) || "teste";

const confirma = await foundry.applications.api.DialogV2.confirm({
	window: { title: "K — Rolar novamente" },
	content: "<p>Rolar novamente <strong>" + titulo + "</strong> (resultado anterior: <strong>" + original.total + "</strong>)?</p>"
});
if (!confirma) return;

const nova = await original.reroll();
await nova.toMessage({
	speaker: ChatMessage.getSpeaker({ actor }),
	flavor: "<strong>K aconselha:</strong> rolando novamente " + titulo + " (antes: " + original.total + ")"
});
await actor.createEmbeddedDocuments("ActiveEffect", [{
	name: MARCA, img: "icons/creatures/magical/construct-iron-stomping-yellow.webp", type: "base",
	duration: { value: null, units: "seconds", expiry: "sceneEnd" },
	description: "<p>Rolagem novamente do K já usada nesta cena.</p>",
	system: { changes: [], targets: [], status: null, onuse: false,
		abilityUse: { description: "", automatic: false, aumenta: false, custo: 0, names: [], types: [] },
		aura: { isAura: false, range: 0 } }
}]);
